    try{if(r.path==='results')await results(d,r.query,token);else if(r.path==='variant')await variant(d,r.query,token);else if(r.path==='downloads')downloads(d);else if(r.path==='about')about(d);else home(d,token);}catch(err){if(token===renderId)failure(err);}
