      '<section class="section"><div class="section-heading"><div><h2>Explore by burden measure</h2><p>'+E(d.name)+' · '+sexes.length+' population strata</p></div></div><div class="measure-grid">'+measures.map(m=>{const list=d.analyses.filter(a=>a.measure===m),mi=info(m);return '<a class="measure-card" href="'+url('results',{disease:d.id,analysis:list[0].id})+'"><span class="code">'+E(mi[0])+'</span><h3>'+E(mi[1])+'</h3><p>'+E(mi[2])+'</p><div class="card-bottom"><span>'+list.length+' analyses · '+nfmt(list.reduce((s,a)=>s+a.row_count,0))+' associations</span><span class="arrow">↗</span></div></a>';}).join('')+'</div></section>'+notice(d)+
      '<section class="section"><div class="section-heading"><div><div class="eyebrow">DISEASE ANALYSES</div><h2>Analysis catalog</h2><p>'+E(d.name)+' · '+nfmt(d.unique_variant_count)+' distinct SNPs across '+nfmt(total)+' association records. A SNP can occur in multiple analyses.</p></div><a href="'+url('downloads',{disease:d.id})+'">Data and documentation ↗</a></div><div class="table-box"><div class="table-scroll"><table><thead><tr><th>Analysis</th><th>Sex</th><th>Measure</th><th>Associations</th><th>Query threshold</th><th></th></tr></thead><tbody>'+d.analyses.map(a=>'<tr><td><a href="'+url('results',{disease:d.id,analysis:a.id})+'">'+E(a.label||a.id)+'</a></td><td>'+E(a.sex)+'</td><td>'+E(info(a.measure)[0])+'</td><td>'+nfmt(a.row_count)+'</td><td class="mono">P &lt; '+fmt(a.selection_p)+'</td><td><a href="'+url('results',{disease:d.id,analysis:a.id})+'" aria-label="View '+E(a.label||a.id)+'">View ↗</a></td></tr>').join('')+'</tbody></table></div></div></section>'+
      '<section class="section two-col"><div class="panel"><h3>Start with a variant</h3><p class="muted small">Search by rsID, variant ID or genomic region. Open a variant to compare its evidence across analyses and inspect country-level reference allele frequencies.</p><div class="workflow"><div><b>01 · Select</b>Disease · Measure · Sex</div><span>→</span><div><b>02 · Explore</b>Search · Filter · Plot</div><span>→</span><div><b>03 · Examine</b>Statistics · Frequencies · Export</div></div></div><div class="panel"><h3>Explore disease burden</h3><p class="muted small">Choose a disease to explore its available burden measures, sex strata, variant statistics and country-level patterns. Each resource provides its own study details and data downloads.</p><a href="#/about">About this resource ↗</a></div></section>';
    document.getElementById('browse-diseases').onclick=e=>{e.preventDefault();document.getElementById('disease-catalog').scrollIntoView({behavior:'smooth',block:'start'});};
