    function updateGenome(){const input=document.getElementById('genome-region').value.trim(),m=/^(?:chr)?([0-9]+|X|Y|MT):(\d+)-(\d+)$/i.exec(input),error=document.getElementById('genome-error'),link=document.getElementById('genome-open');if(!m||+m[2]<1||+m[3]<+m[2]){error.textContent='Enter a valid interval, for example 1:1000000-1100000.';link.removeAttribute('href');return;}const href=ensemblURL(d.build,m[1],+m[2],+m[3]);error.textContent=href?'':'No external browser is configured for this assembly.';if(href)link.href=href;else link.removeAttribute('href');}
